template<FloatingPoint T>
struct Ray final {
    Vector3<T> Origin = Vector3<T>::Zero();
    Vector3<T> Direction = Vector3<T>::Forward();

    constexpr Vector3<T> GetPoint(T distance) const noexcept {
        return Origin + Direction * distance;
    }
};

struct Sphere {
    Vec3 center;
    double radius;
};
